"""OPT-04 evidence tables, regenerated byte-identically from the stored metrics (no GPU, no evaluation).

    python scripts/opt04_make_evidence.py            (write the tables)
    python scripts/opt04_make_evidence.py --check    (exit 1 if any table on disk differs from a fresh build)

Inputs: Model A's registered CH-14b metrics (`results/ch-14b-rtdetr-short-finetune/stageA_epoch1/<split>/<mode>/metrics.json`)
and each OPT-04 candidate's `results/opt-04-model-scale/<name>/<split>/<mode>/metrics.json` (written by
`scripts/opt04_infer.py`, project evaluator), plus `gates.json` and `speed/*.json`.
Outputs in `results/opt-04-model-scale/`: comparison.csv (headline metrics), per_class.csv, density.csv, speed.csv and
report_snippet.md (the same tables in Markdown, evidence only, no conclusions).
"""

from __future__ import annotations

import argparse
import csv
import io
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

from movd import data  # noqa: E402

HERE = data.REPO_ROOT / "results" / "opt-04-model-scale"
MODEL_A = data.REPO_ROOT / "results" / "ch-14b-rtdetr-short-finetune" / "stageA_epoch1"
CANDIDATES = (
    ("P_rtdetrx_e1", "P: RT-DETR-x, epoch 1, CH-13 pipeline (1344)"),
    ("FB_rtdetrl1600_e1", "FB: RT-DETR-l, epoch 1, pipeline at 1600"),
)
HEADLINE = ("mAP", "AP50", "AP75", "AP_small", "AP_medium", "AP_large")


def r4(value) -> str:
    return "" if value is None else f"{value:.4f}"


def models() -> list[tuple[str, str, Path]]:
    """(key, label, evidence root) of Model A and every candidate that has evidence."""
    rows = [("A", "Model A: RT-DETR-l CH-14 epoch 1, CH-13 pipeline (1344)", MODEL_A)]
    rows += [
        (name, label, HERE / name)
        for name, label in CANDIDATES
        if (HERE / name).exists()
    ]
    return rows


def metrics(root: Path, split: str, mode: str) -> dict | None:
    path = root / split / mode / "metrics.json"
    return json.loads(path.read_text(encoding="utf-8")) if path.exists() else None


def to_csv(rows: list[dict]) -> str:
    out = io.StringIO()
    writer = csv.DictWriter(out, fieldnames=list(rows[0]), lineterminator="\n")
    writer.writeheader()
    writer.writerows(rows)
    return out.getvalue()


def to_md(rows: list[dict]) -> str:
    keys = list(rows[0])
    lines = ["| " + " | ".join(keys) + " |", "|" + "---|" * len(keys)]
    lines += ["| " + " | ".join(str(r[k]) for k in keys) + " |" for r in rows]
    return "\n".join(lines) + "\n"


def build() -> dict[str, str]:
    comparison, per_class, density = [], [], []
    for split in ("val_fast", "val_full"):
        for mode in ("pipeline", "single"):
            base = metrics(MODEL_A, split, mode)
            for key, label, root in models():
                m = metrics(root, split, mode)
                if m is None:
                    continue
                row = {
                    "split": split,
                    "mode": mode,
                    "model": key,
                    "label": label,
                    "frames": m["num_images"],
                }
                row.update({k: r4(m["metrics"][k]) for k in HEADLINE})
                row["delta_mAP_vs_A"] = (
                    r4(m["metrics"]["mAP"] - base["metrics"]["mAP"]) if base else ""
                )
                comparison.append(row)
                if mode != "pipeline":
                    continue
                for c, b in zip(m["per_class"], base["per_class"], strict=True):
                    per_class.append(
                        {"split": split, "model": key, "class": c["name"], "num_gt": c["num_gt"],
                         "AP": r4(c["AP"]), "AP50": r4(c["AP50"]), "delta_AP_vs_A": r4(c["AP"] - b["AP"])}
                    )  # fmt: skip
                for d, b in zip(m["density"], base["density"], strict=True):
                    density.append(
                        {"split": split, "model": key, "bin": d["bin"], "num_images": d["num_images"],
                         "num_gt": d["num_gt"], "mAP": r4(d["mAP"]), "delta_mAP_vs_A": r4(d["mAP"] - b["mAP"])}
                    )  # fmt: skip
    speed = []
    for path in sorted((HERE / "speed").glob("*.json")):
        session = json.loads(path.read_text(encoding="utf-8"))
        for r in session["rows"]:
            speed.append(
                {"session": path.stem, "model": r["name"], "mode": r["mode"], "passes": r["passes_per_frame"],
                 "fps": f"{r['fps']:.2f}", "test_minutes_3811": r["test_minutes_3811_frames"],
                 "peak_alloc_GiB": f"{r['peak_cuda_allocated_bytes'] / 2**30:.2f}"}
            )  # fmt: skip
    gates_rows = []
    gates_path = HERE / "gates.json"
    if gates_path.exists():
        gates = json.loads(gates_path.read_text(encoding="utf-8"))
        for cand in ("P", "FB"):
            for gate, value in sorted(gates.get(cand, {}).items()):
                failed = [c["check"] for c in value["checks"] if not c["pass"]]
                gates_rows.append(
                    {"candidate": cand, "gate": gate, "result": "PASS" if value["pass"] else "FAIL",
                     "failed_checks": "; ".join(failed) or "—"}
                )  # fmt: skip

    files = {}
    md = [
        "# OPT-04 evidence tables (generated by scripts/opt04_make_evidence.py; no conclusions)\n"
    ]
    for name, rows, title in (
        (
            "comparison.csv",
            comparison,
            "Headline metrics (project evaluator, maxDets 500)",
        ),
        ("per_class.csv", per_class, "Per-class AP (pipeline)"),
        ("density.csv", density, "Density bins (target objects per frame, pipeline)"),
        (
            "speed.csv",
            speed,
            "Same-session speed (first 30 val_full frames, FP32, batch 1)",
        ),
        ("gates.csv", gates_rows, "Gates (results/opt-04-model-scale/gates.json)"),
    ):
        if rows:
            files[name] = to_csv(rows)
            md.append(f"\n## {title}\n\n" + to_md(rows))
    md.append(
        "\n<!-- TODO (students): interpretation and conclusions are written by Nazar and Marko, not generated. -->\n"
    )
    files["report_snippet.md"] = "".join(md)
    return files


def main() -> None:
    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    parser.add_argument(
        "--check",
        action="store_true",
        help="compare with the tables on disk, write nothing",
    )
    args = parser.parse_args()
    files = build()
    bad = 0
    for name, text in files.items():
        path = HERE / name
        if args.check:
            same = path.exists() and path.read_bytes() == text.encode("utf-8")
            bad += not same
            print(f"{name}: {'identical' if same else 'DIFFERS'}")
        else:
            path.write_bytes(text.encode("utf-8"))
            print(f"wrote {path.relative_to(data.REPO_ROOT).as_posix()}")
    raise SystemExit(1 if bad else 0)


if __name__ == "__main__":
    main()
